import pytest


def shout(xs: list[str]) -> None:
    """Print each string in xs upper-cased, one per line."""
    for x in xs:
        print(x.upper())


def test_shout_basic(capsys: pytest.CaptureFixture[str]) -> None:
    shout(["hello", "world"])
    assert capsys.readouterr().out == "HELLO\nWORLD\n"


def test_shout_empty_list(capsys: pytest.CaptureFixture[str]) -> None:
    shout([])
    assert capsys.readouterr().out == ""


def test_shout_mixed_case_and_symbols(capsys: pytest.CaptureFixture[str]) -> None:
    shout(["MiXeD", "abc123", "!?"])
    assert capsys.readouterr().out == "MIXED\nABC123\n!?\n"


def test_shout_empty_string_prints_blank_line(
    capsys: pytest.CaptureFixture[str],
) -> None:
    shout(["a", "", "b"])
    assert capsys.readouterr().out == "A\n\nB\n"


def test_shout_does_not_mutate_input(capsys: pytest.CaptureFixture[str]) -> None:
    xs = ["abc", "def"]
    shout(xs)
    assert xs == ["abc", "def"]
    capsys.readouterr()


def test_shout_unicode(capsys: pytest.CaptureFixture[str]) -> None:
    shout(["straße", "é"])
    assert capsys.readouterr().out == "STRASSE\nÉ\n"
